<script setup lang="ts">
import { computed, ref, onBeforeUnmount, watch } from 'vue'
import { useFitness } from './store'
import { addDays, volume, setCount, type TrainingRecord, type FitnessItem } from '../../../shared/fitness'
import { localDate } from '../../../shared/date'
import DesignArt from './DesignArt.vue'
import ExerciseImage from './ExerciseImage.vue'
const props=defineProps<{initialId?:string;initialDate?:string}>(),fs=useFitness(),emit=defineEmits<{edit:[record:TrainingRecord];create:[date:string]}>(),today=localDate(),latest=fs.data.records.find(r=>r.id===props.initialId)||[...fs.data.records].sort((a,b)=>b.date.localeCompare(a.date))[0]
const month=ref(latest?.date.slice(0,7)||today.slice(0,7)),picked=ref(latest?.date||props.initialDate||today),selectedId=ref(latest?.id||''),style=ref('cards'),detailTab=ref('items'),playing=ref(false)
let timer:ReturnType<typeof setTimeout>
const records=computed(()=>fs.data.records.filter(r=>r.date.startsWith(month.value)).sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id))),record=computed(()=>records.value.find(r=>r.id===selectedId.value)),index=computed(()=>records.value.findIndex(r=>r.id===selectedId.value)),sameDay=computed(()=>records.value.filter(r=>r.date===picked.value)),minutes=computed(()=>records.value.reduce((s,r)=>s+(r.minutes||0),0)),groups=computed(()=>records.value.reduce((s,r)=>s+setCount(r.items),0))
const dates=computed(()=>{const first=month.value+'-01',offset=(new Date(first+'T12:00:00').getDay()+6)%7,count=new Date(+month.value.slice(0,4),+month.value.slice(5),0).getDate();return Array.from({length:Math.ceil((count+offset)/7)*7},(_,i)=>addDays(first,i-offset))})
const byDate=(date:string)=>fs.data.records.filter(r=>r.date===date),dayMinutes=(date:string)=>byDate(date).reduce((s,r)=>s+(r.minutes||0),0),maxMinutes=computed(()=>Math.max(1,...records.value.map(r=>dayMinutes(r.date))))
const theme=(type:string)=>type==='拉'?'pull':type==='腿'?'legs':type==='推'?'push':'custom',art=(type:string)=>type==='拉'?'lavender':type==='腿'?'pink':'mint',number=(n:number)=>new Intl.NumberFormat('zh-CN',{maximumFractionDigits:1}).format(n)
const weighted=(items:FitnessItem[])=>items.filter(i=>fs.exercise(i.exerciseId)?.measure==='weight'),total=computed(()=>record.value?volume(weighted(record.value.items)):0),previous=computed(()=>record.value?[...fs.data.records].filter(r=>r.date<record.value!.date&&r.type===record.value!.type).sort((a,b)=>b.date.localeCompare(a.date))[0]:undefined),common=computed(()=>record.value&&previous.value?weighted(record.value.items).filter(i=>previous.value!.items.some(x=>x.exerciseId===i.exerciseId)):[]),before=computed(()=>previous.value?volume(previous.value.items.filter(i=>common.value.some(x=>x.exerciseId===i.exerciseId))):0),after=computed(()=>volume(common.value))
function stop(){clearTimeout(timer);playing.value=false}
function select(r:TrainingRecord,manual=true){if(manual)stop();selectedId.value=r.id;picked.value=r.date}
function choose(date:string){stop();picked.value=date;month.value=date.slice(0,7);selectedId.value=byDate(date)[0]?.id||''}
function shift(n:number){stop();const d=new Date(month.value+'-01T12:00:00');d.setMonth(d.getMonth()+n);month.value=localDate(d).slice(0,7);const r=records.value.at(-1);selectedId.value=r?.id||'';picked.value=r?.date||month.value+'-01'}
function tick(){if(index.value>=records.value.length-1){stop();return}select(records.value[index.value+1],false);timer=setTimeout(tick,2200)}
function replay(){if(playing.value){stop();return}playing.value=true;detailTab.value='items';select(records.value[0],false);timer=setTimeout(tick,2200)}
watch(style,stop);onBeforeUnmount(stop)
</script>
<template><div class="history-month-control"><button class="fit-button" aria-label="上个月" @click="shift(-1)">‹</button><strong>{{ month.replace('-',' 年 ') }} 月</strong><button class="fit-button" aria-label="下个月" @click="shift(1)">›</button></div><div class="history-layout">
<section class="fit-card history-calendar-panel"><header class="history-month-head"><div class="month-story"><span class="month-number">{{ month.slice(5) }}</span><div><span class="kicker">训练足迹 / {{ month.slice(0,4) }}</span><h2>每一次，都有迹可循。</h2></div></div><div class="history-month-stats"><div><b>{{ records.length }}<small>次</small></b><span>已记录训练</span></div><div><b>{{ number(minutes) }}<small>分钟</small></b><span>累计训练时长</span></div><div><b>{{ groups }}<small>组</small></b><span>已记录组数</span></div></div></header>
<div class="calendar-style-row"><div class="history-legend"><span v-for="[t,label] in [['push','推 · 上肢'],['pull','拉 · 背部'],['legs','腿 · 臀部']]" :data-tone="t"><i/>{{ label }}</span></div><div class="history-style-switch"><button v-for="[id,label] in [['cards','插画卡片'],['heat','时长热力']]" :class="{active:style===id}" :aria-pressed="style===id" @click="style=id">{{ label }}</button></div></div>
<div class="calendar history-calendar" :class="{'is-heat':style==='heat'}"><span v-for="w in ['一','二','三','四','五','六','日']" class="weekday">周{{ w }}</span><button v-for="date in dates" :key="date" class="cell" :class="{outside:!date.startsWith(month),'has-training':byDate(date).length,selected:picked===date}" :data-date="date" :data-tone="theme(byDate(date)[0]?.type)" :style="{'--heat':.1+dayMinutes(date)/maxMinutes*.27}" :aria-pressed="picked===date" :aria-label="date+'，'+(byDate(date).map(r=>r.title).join('、')||'暂无记录')" @click="choose(date)"><span class="history-date-row"><span class="daynum">{{ +date.slice(8) }}</span><span v-if="byDate(date).length" class="history-cell-check">✓</span><small v-else-if="date===today">今天</small></span><template v-if="byDate(date).length"><span class="history-cell-body"><DesignArt class="history-cell-art" :kind="art(byDate(date)[0].type)"/><span class="history-cell-copy"><b>{{ byDate(date)[0].title }}</b><small>{{ byDate(date).length>1?byDate(date).length+' 条训练':byDate(date)[0].items.length+' 个动作' }} · {{ dayMinutes(date)?dayMinutes(date)+' 分钟':'摘要记录' }}</small></span></span><span class="history-heat-value"><b>{{ dayMinutes(date)||'—' }}</b> 分钟</span></template></button></div>
<div class="history-replay"><button class="replay-button" :disabled="!records.length" :aria-pressed="playing" @click="replay"><span class="replay-symbol">{{ playing?'Ⅱ':'▶' }}</span>{{ playing?'暂停回放':'回放本月' }}</button><div class="replay-path"><button v-for="r in records" :key="r.id" class="replay-stop" :class="{active:selectedId===r.id}" :data-tone="theme(r.type)" :aria-label="r.date+' '+r.title" @click="select(r)"><i/><span>{{ +r.date.slice(8) }}</span></button></div><span class="replay-hint">只回顾已记录的训练</span></div><div class="history-calendar-foot"><span>ⓘ 空白日期表示未记录，不代表休息。</span><span>{{ style==='heat'?'颜色深浅表示已记录时长':'点选日期，右侧查看训练详情' }}</span></div></section>
<aside class="history-sidebar"><section class="fit-card record-inspector"><Transition name="record-memory" mode="out-in"><div v-if="record" :key="record.id" class="record-story" :data-tone="theme(record.type)"><header class="history-detail-nav"><span>{{ record.date.replaceAll('-','.') }} · {{ new Date(record.date+'T12:00:00').toLocaleDateString('zh-CN',{weekday:'short'}) }}</span><div><button :disabled="index<=0" aria-label="上一条训练" @click="select(records[index-1])">‹</button><button :disabled="index===records.length-1" aria-label="下一条训练" @click="select(records[index+1])">›</button></div></header><div v-if="sameDay.length>1" class="same-day-records"><button v-for="(r,i) in sameDay" :class="{active:r.id===record.id}" @click="select(r)">第 {{ i+1 }} 次训练</button></div><div class="record-memory-hero"><span class="memory-eyebrow">本月第 {{ String(index+1).padStart(2,'0') }} 次训练</span><h2>{{ record.title }}</h2><span class="memory-label">✓ 已记录的努力</span><DesignArt class="memory-art" :kind="art(record.type)"/></div><div class="memory-stats"><div><b>{{ record.items.length }}</b><span>动作</span></div><div><b>{{ setCount(record.items) }}</b><span>组数</span></div><div><b>{{ record.minutes??'—' }}</b><span>分钟</span></div></div><div class="memory-tabs" aria-label="详情内容"><button :class="{active:detailTab==='items'}" :aria-pressed="detailTab==='items'" @click="detailTab='items'">动作明细 <span>{{ record.items.length }}</span></button><button :class="{active:detailTab==='notes'}" :aria-pressed="detailTab==='notes'" @click="detailTab='notes'">训练感受<i v-if="record.notes"/></button></div>
<div v-if="detailTab==='items'"><div class="memory-exercises"><details v-for="(item,i) in record.items" :key="i" class="memory-exercise"><summary><span class="memory-exercise-image"><ExerciseImage :image="fs.exercise(item.exerciseId)?.image" :alt="fs.exercise(item.exerciseId)?.name"/><i>{{ String(i+1).padStart(2,'0') }}</i></span><span class="memory-exercise-name"><b>{{ fs.exercise(item.exerciseId)?.name||'已删除动作' }}</b><small>{{ item.sets.length }} 组 · {{ fs.exercise(item.exerciseId)?.measure==='weight'?(item.sets[0]?.weight??'—')+' kg':fs.exercise(item.exerciseId)?.measure==='time'?(item.sets[0]?.duration??'—')+' 秒':(item.sets[0]?.distance??'—')+' 米' }}</small></span><span class="memory-exercise-expand">›</span></summary><div class="memory-sets"><div><span>组</span><span>{{ fs.exercise(item.exerciseId)?.measure==='weight'?'重量':fs.exercise(item.exerciseId)?.measure==='time'?'时长':'距离' }}</span><span>次数</span></div><div v-for="(s,j) in item.sets"><span>{{ j+1 }}</span><b>{{ fs.exercise(item.exerciseId)?.measure==='weight'?(s.weight??'—')+' kg':fs.exercise(item.exerciseId)?.measure==='time'?(s.duration??'—')+' 秒':(s.distance??'—')+' 米' }}</b><b>{{ s.reps??'—' }}</b></div><p v-if="item.notes">{{ item.notes }}</p></div></details></div><p v-if="!record.items.length" class="memory-no-items">本次保存了训练摘要，尚未添加动作明细。</p><details v-if="total" class="memory-volume"><summary><span>已记录负重容量</span><b>{{ number(total) }} <small>kg</small></b> ›</summary><p>按已记录的重量 × 次数累加；自重、时长动作不计入。这个数值不用于判断训练好坏。</p><div v-if="before&&after" class="memory-comparison"><h4>与上次相同动作相比 <span>{{ after>=before?'+':'' }}{{ Math.round((after/before-1)*100) }}%</span></h4><div v-for="(v,i) in [before,after]"><span>{{ (i?record.date:previous!.date).slice(5).replace('-','.') }}</span><i :style="{'--bar':v/Math.max(before,after)*100+'%'}"/><b>{{ number(v) }}</b></div><small>仅比较两次共有的 {{ common.length }} 个负重动作 · kg</small></div></details></div>
<div v-else class="memory-journal"><span class="journal-quote">“</span><p>{{ record.notes||'这次没有填写训练感受。编辑记录，给未来的自己留一句话吧。' }}</p><span>{{ record.date.slice(5).replace('-','.') }} · 留给自己的训练手记</span></div><footer class="history-detail-footer"><span>ⓘ 可随时补充和修改</span><button class="fit-button" @click="stop();emit('edit',record)">✎ 编辑记录</button></footer></div><div v-else key="empty" class="history-empty"><DesignArt kind="note-character"/><span class="kicker">{{ picked.replaceAll('-','.') }}</span><h2>这一天，留白也没关系。</h2><p>还没有保存训练记录。<br/>如果练过了，可以慢慢补上。</p><button class="fit-primary" @click="emit('create',picked)">＋ 补录这一天</button></div></Transition></section><div class="history-side-note"><span>▤</span><span>日历看节奏，详情看内容。<br/>只有实际补录的训练，才会出现在这里。</span></div></aside></div></template>
